package com.djibtout.backend;
import com.djibtout.backend.controller.ReturnController;import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import com.djibtout.backend.service.*;import org.junit.jupiter.api.Test;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ReturnControllerTests{
 ReturnRequestRepository returns=mock(ReturnRequestRepository.class);OrderRepository orders=mock(OrderRepository.class);UserRepository users=mock(UserRepository.class);SellerAccessService access=mock(SellerAccessService.class);SellerEventService events=mock(SellerEventService.class);BuyerNotificationService buyerNotifications=mock(BuyerNotificationService.class);ReturnController controller=new ReturnController(returns,orders,users,access,events,buyerNotifications);
 @Test void unauthenticatedUserCannotListBuyerReturns(){assertEquals(401,controller.mine(null).getStatusCode().value());}
 @Test void sellerCannotUpdateAnotherSellersReturn(){User actor=new User();actor.setEmail("seller@test.local");ReturnRequest request=new ReturnRequest();when(users.findByEmail(actor.getEmail())).thenReturn(Optional.of(actor));when(returns.findById(1L)).thenReturn(Optional.of(request));when(access.canManageOrders(actor,request.getSeller())).thenReturn(false);var auth=new UsernamePasswordAuthenticationToken(actor.getEmail(),"x");assertEquals(403,controller.update(auth,1L,new ReturnController.UpdateReturn(ReturnStatus.APPROVED,null)).getStatusCode().value());}
 @Test void invalidReturnTransitionIsRejected(){User seller=new User();seller.setEmail("seller@test.local");ReturnRequest request=new ReturnRequest();request.setSeller(seller);request.setStatus(ReturnStatus.REJECTED);when(users.findByEmail(seller.getEmail())).thenReturn(Optional.of(seller));when(returns.findById(1L)).thenReturn(Optional.of(request));when(access.canManageOrders(seller,seller)).thenReturn(true);var auth=new UsernamePasswordAuthenticationToken(seller.getEmail(),"x");assertEquals(409,controller.update(auth,1L,new ReturnController.UpdateReturn(ReturnStatus.APPROVED,null)).getStatusCode().value());}
}
